-- Habilitar deduplicación de atajos (función del nuevo HyDE)
hyde.binds.dedup = true

-- Fix (2026-10-09): HyDE dedup includes flags, so locked/repeating custom
-- binds can coexist with defaults. Two Super+W toggles cancel each other.
-- Replace every spelling/flag variant of THIS custom combo before binding it.
local function bind(combo, action, opts)
    local canonical = hyde.binds.canonicalize(combo)
    local remove = {}
    for id, registered in pairs(hyde.binds._active) do
        if hyde.binds.canonicalize(registered) == canonical then
            hl.unbind(registered)
            remove[#remove + 1] = id
        end
    end
    for _, id in ipairs(remove) do
        hyde.binds._active[id] = nil
    end
    hl.unbind(combo)
    return hl.bind(combo, action, opts)
end

