local cycle_fullscreen = function()
    -- No focused window is normal on an empty workspace; do nothing.
    local active_window = hl.get_active_window()
    if not active_window then return end
    local current_state = tonumber(active_window.fullscreen) or 0
    local next_state = (current_state + 1) % 3
    hl.dispatch(
        hl.dsp.window.fullscreen_state(
            {
                internal = next_state,
                client = next_state,
                window = active_window
            }
        )
    )
end

local move_window = function(dir, pix)
    local lut = {l = {-1, 0}, r = {1, 0}, u = {0, -1}, d = {0, 1}}
    lut.left, lut.right, lut.up, lut.down = lut.l, lut.r, lut.u, lut.d
    local m = lut[dir]
    return function()
        -- Fix: an empty workspace has no active window to move.
        local window = hl.get_active_window()
        if not window then return end
        local args = window.floating
            and {x = m[1] * pix, y = m[2] * pix, relative = true}
            or {direction = dir}
        hl.dispatch(hl.dsp.window.move(args))
    end
end

